@Test
public void tombstonesCreatedWhenNoDataInInputIntervalAndExistingSegments() throws Exception {
    Interval interval = Intervals.of("2020-04-01/2020-04-04");
    GranularitySpec granularitySpec = new UniformGranularitySpec(Granularities.DAY, null, false, Collections.singletonList(interval));
    DataSchema dataSchema = new DataSchema("test", null, null, null, granularitySpec, null);
    // no segments will be pushed when all rows are thrown away, assume that:
    List<DataSegment> pushedSegments = Collections.emptyList();
    // Assume used segments exist:
    DataSegment existingUsedSegment = DataSegment.builder().dataSource("test").interval(interval).version("oldVersion").size(100).build();
    Assert.assertFalse(existingUsedSegment.isTombstone());
    Mockito.when(taskActionClient.submit(any(TaskAction.class))).thenReturn(Collections.singletonList(existingUsedSegment));
    TombstoneHelper tombstoneHelper = new TombstoneHelper(pushedSegments, dataSchema, taskActionClient);
    List<Interval> tombstoneIntervals = tombstoneHelper.computeTombstoneIntervals();
    Assert.assertEquals(3, tombstoneIntervals.size());
    Map<Interval, SegmentIdWithShardSpec> intervalToVersion = new HashMap<>();
    for (Interval ti : tombstoneIntervals) {
        intervalToVersion.put(ti, new SegmentIdWithShardSpec("test", ti, "newVersion", new TombstoneShardSpec()));
    }
    Set<DataSegment> tombstones = tombstoneHelper.computeTombstones(intervalToVersion);
    Assert.assertEquals(3, tombstones.size());
    tombstones.forEach(ts -> Assert.assertTrue(ts.isTombstone()));
}

@Before
public void setup() {
    rowIngestionMeters = new SimpleRowIngestionMeters();
    parseExceptionHandler = Mockito.spy(new ParseExceptionHandler(rowIngestionMeters, true, Integer.MAX_VALUE, // do not use Integer.MAX_VALUE since it will create an object array of this length
    1024));
}

@Test
public void testParseExceptionSaveExceptionCause() {
    // This iterator throws ParseException every other call to hasNext().
    final CloseableIterator<InputRow> parseExceptionThrowingIterator = new CloseableIterator<InputRow>() {

        final int numRowsToIterate = ROWS.size() * 2;

        int currentIndex = 0;

        int nextIndex = 0;

        @Override
        public boolean hasNext() {
            currentIndex = nextIndex++;
            if (currentIndex % 2 == 0) {
                return currentIndex < numRowsToIterate;
            } else {
                try {
                    throw new IllegalArgumentException("this is the root cause of the exception!");
                } catch (Exception e) {
                    throw new ParseException(null, e, "Parse exception at [%d]", currentIndex);
                }
            }
        }

        @Override
        public InputRow next() {
            return ROWS.get(currentIndex / 2);
        }

        @Override
        public void close() {
        }
    };
    final FilteringCloseableInputRowIterator rowIterator = new FilteringCloseableInputRowIterator(parseExceptionThrowingIterator, row -> true, rowIngestionMeters, parseExceptionHandler);
    final List<InputRow> filteredRows = new ArrayList<>();
    rowIterator.forEachRemaining(filteredRows::add);
    ArgumentCaptor<Exception> exceptionArgumentCaptor = ArgumentCaptor.forClass(Exception.class);
    Mockito.verify(parseExceptionHandler, Mockito.times(6)).logParseExceptionHelper(exceptionArgumentCaptor.capture());
    Exception parseException = exceptionArgumentCaptor.getValue();
    Assert.assertTrue(parseException.getMessage().contains("Parse exception at"));
    Assert.assertNotNull(parseException.getCause());
    Assert.assertTrue(parseException.getCause().getMessage().contains("this is the root cause of the exception!"));
    Assert.assertEquals(IllegalArgumentException.class, parseException.getCause().getClass());
    Assert.assertEquals(ROWS, filteredRows);
    Assert.assertEquals(ROWS.size(), rowIngestionMeters.getUnparseable());
}

